(()=>{'use strict';const $=id=>document.getElementById(id);$('refresh-health').onclick=async()=>{const box=$('health-results');box.textContent='Checking the live backend…';try{const response=await fetch('/api/designer/health');const result=await response.json();if(!response.ok)throw Error(result.error);box.replaceChildren();for(const [name,value]of Object.entries(result)){const line=document.createElement('p');line.textContent=name.charAt(0).toUpperCase()+name.slice(1)+': '+value;box.append(line);}}catch(e){box.textContent=e.message||'Backend unavailable';}};})();
